SELECT (DATE_TRUNC('DAY', "USAGE_DAY")) AS "TIME_BUCKET", SUM(TOKENS) AS "AI_TOTAL_TOKENS" FROM (SELECT u.FUNCTION_NAME AS FUNCTION_NAME, u.MODEL_NAME AS MODEL_NAME, u.USAGE_DAY AS USAGE_DAY, u.TOKENS AS TOKENS, (CAST(u.TOKEN_CREDITS AS DECIMAL(38, 9))) AS TOKEN_CREDITS, u.CALL_COUNT AS CALL_COUNT, (CAST(COALESCE(m.ACCOUNT_CREDITS, 0) AS DECIMAL(38, 9))) AS ACCOUNT_CREDITS_DAY, u.ACCOUNT_NAME AS ACCOUNT_NAME /* The account these rows came from (see the ACCOUNT_OF shim). */ FROM (SELECT "FUNCTION_NAME" AS FUNCTION_NAME, "MODEL_NAME" AS MODEL_NAME, CAST((DATE_TRUNC('DAY', (TRY_CAST("START_TIME" AS TIMESTAMP)))) AS DATE) AS USAGE_DAY, ("_ACCOUNT") AS ACCOUNT_NAME, SUM("TOKENS") AS TOKENS, (CAST(SUM("TOKEN_CREDITS") AS DECIMAL(38, 9))) AS TOKEN_CREDITS, COUNT(*) AS CALL_COUNT FROM cortex_functions_usage_history GROUP BY 1, 2, 3, 4) AS u LEFT JOIN (SELECT CAST("USAGE_DATE" AS DATE) AS USAGE_DAY, ("_ACCOUNT") AS ACCOUNT_NAME, (CAST(SUM("CREDITS_USED") AS DECIMAL(38, 9))) AS ACCOUNT_CREDITS FROM metering_daily_history GROUP BY 1, 2) AS m ON m.USAGE_DAY = u.USAGE_DAY AND COALESCE(m.ACCOUNT_NAME, '') = COALESCE(u.ACCOUNT_NAME, '')) AS base GROUP BY (DATE_TRUNC('DAY', "USAGE_DAY")) ORDER BY "AI_TOTAL_TOKENS" DESC, "TIME_BUCKET" LIMIT 100
